draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // life event changing moment
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 30 * Math.sin(t), H/2 + 50, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 30 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();

  // event circle
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 50, 20 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
